const agvModdle = { name:'AGV Workflow', uri:'http://kunling.com/schema/agv-workflow', prefix:'agv', xml:{tagAlias:'lowerCase'}, types:[{ name:'ActionTask', extends:['bpmn:ServiceTask'], properties:[
  {name:'actionKey',isAttr:true,type:'String'}, {name:'actionDefinitionId',isAttr:true,type:'String'}, {name:'actionRevision',isAttr:true,type:'String'}, {name:'executionParams',isAttr:true,type:'String'},
  {name:'failureStrategy',isAttr:true,type:'String'}, {name:'completionBasis',isAttr:true,type:'String'}, {name:'subProcessXml',isAttr:true,type:'String'},
] },{name:'FlowRouting',extends:['bpmn:SequenceFlow'],properties:[{name:'sourceSide',isAttr:true,type:'String'},{name:'targetSide',isAttr:true,type:'String'}]}] }
const route = useRoute()
const editingId = Number(route.query.id) || null
const meta = reactive({id:editingId,templateNumber:'',templateName:'',applicableObject:'复合机器人',status:'新增'})
const canvasHost=ref(null), modeler=ref(null), loading=ref(true), saving=ref(false), dirty=ref(false), actions=ref([]), actionKeyword=ref(''), selectedElement=ref(null), diagramRevision=ref(0), zoomLevel=ref(100)
const loadedEditorData=ref({})
const childMode=ref(false), childParentId=ref(''), childParentName=ref(''), mainXmlCache=ref('')
const childPreviewVisible=ref(false),childEditorVisible=ref(false),childPreviewParent=shallowRef(null),selectedChildIndex=ref(-1),childRows=ref([])
const draggingChildIndex=ref(-1),childDropIndex=ref(-1)
const actionScenes=ref([]),childActions=ref([]),childActionsLoading=ref(false),childSaving=ref(false)
let pendingSourceSide='right',pendingTargetSide='left'
const selectedType=computed(()=>selectedElement.value?.businessObject?.$type||'')
const isActionTask=computed(()=>selectedType.value==='bpmn:ServiceTask')
const childParentSequence=computed(()=>{diagramRevision.value;const parent=childPreviewParent.value;if(!parent||!modeler.value)return'';const index=orderedFlowElements().findIndex(item=>item.id===parent.id);return index>=0?`${index+1}·${parent.businessObject.name||parent.id}`:parent.businessObject.name||parent.id})
const builtInActionDefinitionIds={'MOVE':'20000000-0000-4000-8000-000000000001','PICK':'20000000-0000-4000-8000-000000000002','ARM.PICK':'20000000-0000-4000-8000-000000000002','PLACE':'20000000-0000-4000-8000-000000000003','ARM.PLACE':'20000000-0000-4000-8000-000000000003','ARM.PICK_BATCH':'20000000-0000-4000-8000-000000000004','ARM.PLACE_BATCH':'20000000-0000-4000-8000-000000000005','HOME':'20000000-0000-4000-8000-000000000006','ARM.HOME':'20000000-0000-4000-8000-000000000006','CAPTURE':'20000000-0000-4000-8000-000000000007','VISION.CAPTURE':'20000000-0000-4000-8000-000000000007'}
const paletteGroups=computed(()=>{if(childMode.value)return[{label:'子节点',items:childActions.value}];const q=actionKeyword.value.trim().toLowerCase();return[{label:'主节点',items:actionScenes.value.map(item=>{const remote=actions.value.find(row=>row.actionKey===item.code||String(row.actionKey||'').endsWith(`.${item.code}`));return{name:item.name,actionKey:item.code,sceneCode:item.code,actionDefinitionId:remote?.actionDefinitionId||builtInActionDefinitionIds[item.code]||'',actionRevision:remote?.actionRevision||'1',status:'ACTIVE'}}).filter(item=>!q||`${item.name} ${item.actionKey}`.toLowerCase().includes(q))}]})
const allPaletteActions=computed(()=>paletteGroups.value.flatMap(group=>group.items))
const propertyForm=reactive({name:'',actionKey:'',actionDefinitionId:'',actionRevision:'',executionParams:'',failureStrategy:'RETRY_THEN_SUSPEND',completionBasis:''})
const escapeXml=v=>String(v??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'})[c])

const emptyDiagram=(name='新建流程模板')=>`<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:agv="http://kunling.com/schema/agv-workflow" id="Definitions_AGV" targetNamespace="http://kunling.com/workflow">
<bpmn:process id="Process_AGV" name="${escapeXml(name)}" isExecutable="true"><bpmn:startEvent id="StartEvent_1" name="开始"><bpmn:outgoing>Flow_1</bpmn:outgoing></bpmn:startEvent><bpmn:serviceTask id="Activity_1" name="移动" agv:actionKey="MOVE" agv:actionDefinitionId="${builtInActionDefinitionIds.MOVE}" agv:failureStrategy="RETRY_THEN_SUSPEND"><bpmn:incoming>Flow_1</bpmn:incoming><bpmn:outgoing>Flow_2</bpmn:outgoing></bpmn:serviceTask><bpmn:endEvent id="EndEvent_1" name="结束"><bpmn:incoming>Flow_2</bpmn:incoming></bpmn:endEvent><bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="Activity_1"/><bpmn:sequenceFlow id="Flow_2" sourceRef="Activity_1" targetRef="EndEvent_1"/></bpmn:process>
<bpmndi:BPMNDiagram id="BPMNDiagram_1"><bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_AGV"><bpmndi:BPMNShape id="StartEvent_1_di" bpmnElement="StartEvent_1"><dc:Bounds x="160" y="192" width="36" height="36"/></bpmndi:BPMNShape><bpmndi:BPMNShape id="Activity_1_di" bpmnElement="Activity_1"><dc:Bounds x="270" y="170" width="100" height="80"/></bpmndi:BPMNShape><bpmndi:BPMNShape id="EndEvent_1_di" bpmnElement="EndEvent_1"><dc:Bounds x="445" y="192" width="36" height="36"/></bpmndi:BPMNShape><bpmndi:BPMNEdge id="Flow_1_di" bpmnElement="Flow_1"><di:waypoint x="196" y="210"/><di:waypoint x="270" y="210"/></bpmndi:BPMNEdge><bpmndi:BPMNEdge id="Flow_2_di" bpmnElement="Flow_2"><di:waypoint x="370" y="210"/><di:waypoint x="445" y="210"/></bpmndi:BPMNEdge></bpmndi:BPMNPlane></bpmndi:BPMNDiagram></bpmn:definitions>`
const blankMainDiagram=name=>`<?xml version="1.0" encoding="UTF-8"?><bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:agv="http://kunling.com/schema/agv-workflow" id="Definitions_AGV" targetNamespace="http://kunling.com/workflow"><bpmn:process id="Process_AGV" name="${escapeXml(name)}" isExecutable="true"/><bpmndi:BPMNDiagram id="BPMNDiagram_1"><bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_AGV"/></bpmndi:BPMNDiagram></bpmn:definitions>`
function parseChildRows(xml){
  if(!xml)return[]
  try{return[...new DOMParser().parseFromString(xml,'application/xml').querySelectorAll('serviceTask, receiveTask')].map((node,index)=>({id:`child-${Date.now()}-${index}`,order:index+1,name:node.getAttribute('name')||`子节点 ${index+1}`,actionKey:node.getAttributeNS(agvModdle.uri,'actionKey')||node.getAttribute('agv:actionKey')||'',actionRevision:node.getAttributeNS(agvModdle.uri,'actionRevision')||node.getAttribute('agv:actionRevision')||'1',executionParams:node.getAttributeNS(agvModdle.uri,'executionParams')||node.getAttribute('agv:executionParams')||'',failureStrategy:node.getAttributeNS(agvModdle.uri,'failureStrategy')||node.getAttribute('agv:failureStrategy')||'RETRY_THEN_SUSPEND',completionBasis:node.getAttributeNS(agvModdle.uri,'completionBasis')||node.getAttribute('agv:completionBasis')||''}))}catch{return[]}
}
function childXmlFromRows(name,rows){
  const tasks=rows.map((row,index)=>`<bpmn:receiveTask id="Child_${index+1}" name="${escapeXml(row.name)}" agv:actionKey="${escapeXml(row.actionKey)}" agv:actionRevision="${escapeXml(row.actionRevision||'1')}" agv:executionParams="${escapeXml(row.executionParams||'')}" agv:failureStrategy="${escapeXml(row.failureStrategy||'RETRY_THEN_SUSPEND')}" agv:completionBasis="${escapeXml(row.completionBasis||'')}">${index?`<bpmn:incoming>ChildFlow_${index}</bpmn:incoming>`:''}${index<rows.length-1?`<bpmn:outgoing>ChildFlow_${index+1}</bpmn:outgoing>`:''}</bpmn:receiveTask>`).join('')
  const flows=rows.slice(1).map((_,index)=>`<bpmn:sequenceFlow id="ChildFlow_${index+1}" sourceRef="Child_${index+1}" targetRef="Child_${index+2}"/>`).join('')
  const shapes=rows.map((_,index)=>`<bpmndi:BPMNShape id="Child_${index+1}_di" bpmnElement="Child_${index+1}"><dc:Bounds x="${120+index*220}" y="160" width="180" height="66"/></bpmndi:BPMNShape>`).join('')
  const edges=rows.slice(1).map((_,index)=>`<bpmndi:BPMNEdge id="ChildFlow_${index+1}_di" bpmnElement="ChildFlow_${index+1}"><di:waypoint x="${300+index*220}" y="193"/><di:waypoint x="${340+index*220}" y="193"/></bpmndi:BPMNEdge>`).join('')
  return`<?xml version="1.0" encoding="UTF-8"?><bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:agv="${agvModdle.uri}" id="Definitions_Child" targetNamespace="http://kunling.com/workflow"><bpmn:process id="Process_Child" name="${escapeXml(name)}" isExecutable="true">${tasks}${flows}</bpmn:process><bpmndi:BPMNDiagram id="BPMNDiagram_Child"><bpmndi:BPMNPlane id="BPMNPlane_Child" bpmnElement="Process_Child">${shapes}${edges}</bpmndi:BPMNPlane></bpmndi:BPMNDiagram></bpmn:definitions>`
}
function showChildPreview(element){if(childMode.value||element?.type!=='bpmn:ServiceTask')return;childPreviewParent.value=element;childRows.value=parseChildRows(element.businessObject.subProcessXml);selectedChildIndex.value=-1;childPreviewVisible.value=true}
function sceneCodeFor(actionKey){const key=String(actionKey||'').toUpperCase();return actionScenes.value.find(item=>item.code===key)?.code||(['PICK','PLACE','MOVE','HOME','CAPTURE'].find(code=>key.includes(code))||key)}
async function openChildEditor(){if(!childPreviewParent.value)return;childActionsLoading.value=true;childEditorVisible.value=true;childPreviewVisible.value=false;try{const sceneCode=sceneCodeFor(childPreviewParent.value.businessObject.actionKey);const rows=await listActionSceneOperations(sceneCode);childActions.value=(rows||[]).map(item=>({name:item.name,actionKey:item.code,sceneCode,actionRevision:'1',status:'ACTIVE'}))}catch(error){childActions.value=[];ElMessage.error(`子节点动作加载失败：${error.message}`)}finally{childActionsLoading.value=false}}
function addChildAction(action){childRows.value.push({id:`child-${Date.now()}`,order:childRows.value.length+1,name:action.name,actionKey:action.actionKey,actionRevision:action.actionRevision||'1',executionParams:'',failureStrategy:'RETRY_THEN_SUSPEND',completionBasis:''});selectedChildIndex.value=childRows.value.length-1}
function startChildDrag(event,index){draggingChildIndex.value=index;childDropIndex.value=index;selectedChildIndex.value=index;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(index))}
function overChildDrag(event,index){event.preventDefault();event.dataTransfer.dropEffect='move';childDropIndex.value=index}
function dropChild(event,index){event.preventDefault();const from=draggingChildIndex.value;if(from<0||from===index)return endChildDrag();const [moved]=childRows.value.splice(from,1);childRows.value.splice(index,0,moved);childRows.value.forEach((item,i)=>item.order=i+1);selectedChildIndex.value=index;endChildDrag()}
function endChildDrag(){draggingChildIndex.value=-1;childDropIndex.value=-1}
function removeChild(index){childRows.value.splice(index,1);childRows.value.forEach((item,i)=>item.order=i+1);selectedChildIndex.value=Math.min(index,childRows.value.length-1)}
function childStepParams(value){if(!value)return{};if(typeof value==='object')return value;try{return JSON.parse(value)}catch{return{}}}
async function saveChildEditor(){const parent=childPreviewParent.value;if(!parent)return ElMessage.error('未找到对应主节点');if(!childRows.value.length)return ElMessage.warning('请至少添加一个子节点');childSaving.value=true;try{const result=await createActionDefinition({name:parent.businessObject.name||parent.id,enabled:false,timeoutMs:60000,steps:childRows.value.map((row,index)=>({stepId:`step-${String(index+1).padStart(2,'0')}`,operation:row.actionKey,params:childStepParams(row.executionParams),gate:true,onFailure:{rules:[],defaultDirective:{action:'STOP_AND_REPORT',maxRetries:0,delayMs:0}}}))}),definitionId=result?.definition?.id;if(!definitionId)throw new Error('接口未返回 Action 定义 ID');modeler.value.get('modeling').updateProperties(parent,{actionDefinitionId:definitionId,actionRevision:'1',subProcessXml:childXmlFromRows(`${parent.businessObject.name||parent.id} 子流程`,childRows.value)});dirty.value=true;childEditorVisible.value=false;childPreviewVisible.value=true;refreshAllOverlays();ElMessage.success('子节点已保存，Action 定义已绑定到主节点')}catch(error){ElMessage.error(`子节点保存失败：${error.message}`)}finally{childSaving.value=false}}

function normalizeActions(rows){const fallback=[['移动','MOVE'],['单次取料','ARM.PICK'],['单次放料','ARM.PLACE'],['复合取料','ARM.BATCH_PICK'],['复合放料','ARM.BATCH_PLACE'],['协作臂归零','ARM.HOME'],['现场拍照','VISION.CAPTURE'],['自动门','DOOR.OPEN'],['手套箱','GLOVEBOX.RUN'],['贴标机台','LABEL.RUN'],['后处理机台','POST.RUN']].map(([name,actionKey])=>({name,actionKey,actionDefinitionId:builtInActionDefinitionIds[actionKey]||'',actionRevision:'1',status:'ACTIVE'}));return rows?.length?rows.map(r=>{const definition=r.definition||r;const rawName=definition.name||definition.displayName||r.displayName||r.actionKey||'';const actionKey=r.actionKey||definition.actionKey||rawName.split(/[（(\s]/)[0];return{name:rawName||actionKey,actionKey,actionDefinitionId:definition.id||r.actionDefinitionId||r.actionId||'',actionRevision:String(r.revision||definition.revision||''),status:r.status||(definition.enabled===false?'DISABLED':'ACTIVE')}}):fallback}
function selectElement(element){selectedElement.value=element;const b=element?.businessObject;Object.assign(propertyForm,{name:b?.name||'',actionKey:b?.actionKey||'',actionDefinitionId:b?.actionDefinitionId||'',actionRevision:b?.actionRevision||'',executionParams:b?.executionParams||'',failureStrategy:b?.failureStrategy||'RETRY_THEN_SUSPEND',completionBasis:b?.completionBasis||''})}
function removeDiagramElement(element){if(!element)return;modeler.value.get('modeling').removeElements([element]);modeler.value.get('selection').select(null)}
function startConnection(event,element,side){if(element.outgoing?.some(flow=>flow.type==='bpmn:SequenceFlow'))return;event.stopPropagation();event.preventDefault();pendingSourceSide=side;const x=side==='left'?element.x:element.x+element.width;modeler.value.get('connect').start(event,element,{x,y:element.y+element.height/2})}
function connectionSide(connection,endpoint,isSource){
  const property=isSource?'sourceSide':'targetSide',temporary=isSource?'_agvSourceSide':'_agvTargetSide',explicit=connection.businessObject?.[property]||connection[temporary]
  if(explicit)return explicit
  const waypoint=isSource?connection.waypoints?.[0]:connection.waypoints?.at(-1)
  if(waypoint&&endpoint){
    const leftDistance=Math.abs(waypoint.x-endpoint.x),rightDistance=Math.abs(waypoint.x-(endpoint.x+endpoint.width))
    if(Math.min(leftDistance,rightDistance)<=2)return leftDistance<=rightDistance?'left':'right'
  }
  const other=isSource?connection.target:connection.source
  return other&&other.x+other.width/2<endpoint.x+endpoint.width/2?'left':'right'
}
function compactWaypoints(points){
  const unique=points.filter((point,index)=>!index||point.x!==points[index-1].x||point.y!==points[index-1].y)
  return unique.filter((point,index)=>{
    if(!index||index===unique.length-1)return true
    const previous=unique[index-1],next=unique[index+1]
    return !(previous.x===point.x&&point.x===next.x)&&!(previous.y===point.y&&point.y===next.y)
  })
}
function orthogonalWaypoints(connection){
  const source=connection?.source,target=connection?.target
  if(!source||!target)return[]
  const sourceSide=connectionSide(connection,source,true),targetSide=connectionSide(connection,target,false)
  const sourcePoint={x:sourceSide==='left'?source.x:source.x+source.width,y:source.y+source.height/2}
  const targetPoint={x:targetSide==='left'?target.x:target.x+target.width,y:target.y+target.height/2}
  const clearance=36
  if(sourceSide===targetSide){
    const outerX=sourceSide==='right'
      ?Math.max(sourcePoint.x,targetPoint.x)+clearance
      :Math.min(sourcePoint.x,targetPoint.x)-clearance
    return compactWaypoints([sourcePoint,{x:outerX,y:sourcePoint.y},{x:outerX,y:targetPoint.y},targetPoint])
  }
  const sourceExitX=sourcePoint.x+(sourceSide==='left'?-clearance:clearance)
  const targetEntryX=targetPoint.x+(targetSide==='left'?-clearance:clearance)
  const facingWithSpace=(
    (sourceSide==='right'&&targetSide==='left'&&sourcePoint.x<=targetPoint.x)||
    (sourceSide==='left'&&targetSide==='right'&&sourcePoint.x>=targetPoint.x)
  )
  if(facingWithSpace){
    if(Math.abs(sourcePoint.y-targetPoint.y)<1)return[sourcePoint,targetPoint]
    const middleX=(sourcePoint.x+targetPoint.x)/2
    return compactWaypoints([sourcePoint,{x:middleX,y:sourcePoint.y},{x:middleX,y:targetPoint.y},targetPoint])
  }
  const verticalGap=target.y-(source.y+source.height)
  const reverseVerticalGap=source.y-(target.y+target.height)
  let routeY
  if(verticalGap>=clearance*2)routeY=(source.y+source.height+target.y)/2
  else if(reverseVerticalGap>=clearance*2)routeY=(target.y+target.height+source.y)/2
  else routeY=Math.min(source.y,target.y)-clearance
  return compactWaypoints([sourcePoint,{x:sourceExitX,y:sourcePoint.y},{x:sourceExitX,y:routeY},{x:targetEntryX,y:routeY},{x:targetEntryX,y:targetPoint.y},targetPoint])
}
function sameWaypoints(current,next){return current?.length===next.length&&current.every((point,index)=>Math.abs(point.x-next[index].x)<.5&&Math.abs(point.y-next[index].y)<.5)}
function normalizeSequenceFlows(){
  if(!modeler.value)return
  const modeling=modeler.value.get('modeling')
  modeler.value.get('elementRegistry').filter(element=>element.type==='bpmn:SequenceFlow').forEach(connection=>{
    const waypoints=orthogonalWaypoints(connection)
    if(waypoints.length&&!sameWaypoints(connection.waypoints,waypoints))modeling.updateWaypoints(connection,waypoints)
  })
}
function normalizeNodeBounds(){const modeling=modeler.value.get('modeling');modeler.value.get('elementRegistry').filter(element=>['bpmn:StartEvent','bpmn:ServiceTask','bpmn:EndEvent'].includes(element.type)&&(element.width!==180||element.height!==66)).forEach(element=>modeling.resizeShape(element,{x:element.x+(element.width-180)/2,y:element.y+(element.height-66)/2,width:180,height:66}))}
function orderedFlowElements(){const registry=modeler.value.get('elementRegistry'),supported=registry.filter(e=>['bpmn:StartEvent','bpmn:ServiceTask','bpmn:EndEvent'].includes(e.type)),start=supported.find(e=>e.type==='bpmn:StartEvent'),ordered=[],seen=new Set();let current=start;while(current&&!seen.has(current.id)){seen.add(current.id);ordered.push(current);current=current.outgoing?.find(flow=>flow.type==='bpmn:SequenceFlow')?.target}return[...ordered,...supported.filter(element=>!seen.has(element.id))]}
function canvasNodeIcon(element){if(element.type==='bpmn:StartEvent')return'➤';if(element.type==='bpmn:EndEvent')return'♟';return actionGlyph({actionKey:element.businessObject.actionKey})}
function refreshNodeOverlays(){if(!modeler.value)return;const overlays=modeler.value.get('overlays'),canvas=modeler.value.get('canvas'),registry=modeler.value.get('elementRegistry');overlays.clear();registry.filter(e=>e.type!=='label').forEach(element=>canvas.removeMarker(element,'agv-card-node'));registry.filter(e=>e.type==='label').forEach(element=>canvas.removeMarker(element,'agv-card-label'));const nodes=orderedFlowElements(),nodeIds=new Set(nodes.map(element=>element.id));registry.filter(element=>element.type==='label'&&nodeIds.has(element.labelTarget?.id)).forEach(label=>canvas.addMarker(label,'agv-card-label'));nodes.forEach((element,index)=>{canvas.addMarker(element,'agv-card-node');const card=document.createElement('div');card.className=`agv-canvas-node${selectedElement.value?.id===element.id?' selected':''}`;card.dataset.elementId=element.id;const title=document.createElement('strong');title.textContent=`${index+1} · ${element.businessObject.name||element.type.replace('bpmn:','')}`;const type=document.createElement('small');type.textContent=element.type==='bpmn:ServiceTask'?(childMode.value?'子节点':'主节点'):'通用节点';const icon=document.createElement('span');icon.className='agv-canvas-node-icon';icon.textContent=canvasNodeIcon(element);const remove=document.createElement('button');remove.type='button';remove.className='agv-canvas-node-delete';remove.textContent='×';remove.title='删除节点';remove.addEventListener('click',event=>{event.stopPropagation();removeDiagramElement(element)});card.append(title,type,icon,remove);if(element.type==='bpmn:ServiceTask'&&!childMode.value){const child=document.createElement('button');child.type='button';child.className='agv-canvas-node-child';const count=parseChildRows(element.businessObject.subProcessXml).length;child.textContent=`${count} 子节点 ›`;child.addEventListener('click',event=>{event.stopPropagation();showChildPreview(element)});card.append(child)}overlays.add(element,{position:{left:(element.width-180)/2,top:(element.height-66)/2},html:card})});const connection=selectedElement.value?.type==='bpmn:SequenceFlow'?selectedElement.value:null;if(connection?.waypoints?.length){const first=connection.waypoints[0],last=connection.waypoints.at(-1),minX=Math.min(...connection.waypoints.map(point=>point.x)),minY=Math.min(...connection.waypoints.map(point=>point.y)),button=document.createElement('button');button.type='button';button.className='agv-connection-delete';button.textContent='×';button.title='删除连线';button.addEventListener('click',event=>{event.stopPropagation();removeDiagramElement(connection)});overlays.add(connection,{position:{left:(first.x+last.x)/2-minX-11,top:(first.y+last.y)/2-minY-11},html:button})}}
function setNodeHover(element,hovered){const card=document.querySelector(`.agv-canvas-node[data-element-id="${element?.id}"]`);card?.classList.toggle('hovered',hovered)}
function moveCardWithShape(event){const shape=event.context?.shape,card=document.querySelector(`.agv-canvas-node[data-element-id="${shape?.id}"]`);if(card){const scale=modeler.value.get('canvas').zoom();card.style.transform=`translate(${event.dx*scale}px,${event.dy*scale}px)`}}
function resetMovingCard(event){const shape=event.context?.shape,card=document.querySelector(`.agv-canvas-node[data-element-id="${shape?.id}"]`);if(card)card.style.transform=''}
function refreshConnectionPorts(){modeler.value.get('elementRegistry').filter(element=>['bpmn:StartEvent','bpmn:ServiceTask','bpmn:EndEvent'].includes(element.type)).forEach(element=>{const card=document.querySelector(`.agv-canvas-node[data-element-id="${element.id}"]`);if(!card||card.querySelector('.agv-node-port'))return;const occupied=element.outgoing?.some(flow=>flow.type==='bpmn:SequenceFlow'),canStart=element.type!=='bpmn:EndEvent';['left','right'].forEach(side=>{const port=document.createElement('button');port.type='button';port.className=`agv-node-port agv-node-port-${side}${occupied?' occupied':''}${canStart?'':' target-only'}`;port.title=canStart?(occupied?'已有后续连线':`从节点${side==='left'?'左':'右'}侧拖出连线`):`结束节点${side==='left'?'左':'右'}侧连线入口`;if(canStart)port.addEventListener('mousedown',event=>startConnection(event,element,side));card.append(port)})})}
function refreshAllOverlays(){refreshNodeOverlays();refreshConnectionPorts()}
function setConnectionTarget(element,active){const card=document.querySelector(`.agv-canvas-node[data-element-id="${element?.id}"]`);card?.classList.toggle('connection-target',active)}
function connectionTargetSide(event,target){const card=document.querySelector(`.agv-canvas-node[data-element-id="${target?.id}"]`),clientX=event.originalEvent?.clientX;if(card&&Number.isFinite(clientX)){const bounds=card.getBoundingClientRect();return clientX<bounds.left+bounds.width/2?'left':'right'}return event.x<target.x+target.width/2?'left':'right'}
function bindEvents(instance){const bus=instance.get('eventBus');bus.on('directEditing.activate.allowed',2000,()=>false);bus.on('selection.changed',({newSelection})=>{selectElement(newSelection[0]||null);queueMicrotask(refreshAllOverlays)});bus.on('commandStack.changed',()=>{diagramRevision.value++;if(!loading.value)dirty.value=true;queueMicrotask(refreshAllOverlays);requestAnimationFrame(refreshAllOverlays)});bus.on('connect.start',()=>canvasHost.value?.classList.add('is-connecting'));bus.on(['connect.cleanup','connect.canceled'],()=>canvasHost.value?.classList.remove('is-connecting'));bus.on('connect.move',800,event=>{const context=event.context,target=context.target||context.hover,source=context.source||context.start;if(!target||!source||!context.canExecute)return;const targetSide=connectionTargetSide(event,target),preview={source,target,_agvSourceSide:pendingSourceSide,_agvTargetSide:targetSide,businessObject:{sourceSide:pendingSourceSide,targetSide}},waypoints=orthogonalWaypoints(preview);instance.get('connectionPreview').drawPreview(context,context.canExecute,{source,target,connectionStart:waypoints[0],connectionEnd:waypoints.at(-1),waypoints,noLayout:true,noCropping:true})});bus.on('connect.end',2000,event=>{const target=event.hover||event.context?.hover;if(target){pendingTargetSide=connectionTargetSide(event,target);event.x=pendingTargetSide==='left'?target.x:target.x+target.width;event.y=target.y+target.height/2}});bus.on(['commandStack.connection.create.postExecuted','commandStack.connection.reconnect.postExecuted'],event=>{const connection=event.context?.connection;if(connection){connection._agvSourceSide=pendingSourceSide;connection._agvTargetSide=pendingTargetSide;connection.businessObject.sourceSide=pendingSourceSide;connection.businessObject.targetSide=pendingTargetSide}queueMicrotask(normalizeSequenceFlows)});bus.on('shape.move.move',moveCardWithShape);bus.on(['shape.move.end','shape.move.cleanup'],event=>{resetMovingCard(event);queueMicrotask(normalizeSequenceFlows)});bus.on('connect.hover',({hover})=>setConnectionTarget(hover,true));bus.on(['connect.out','connect.cleanup'],({hover,context})=>setConnectionTarget(hover||context?.hover,false));bus.on('element.hover',({element})=>setNodeHover(element,true));bus.on('element.out',({element})=>setNodeHover(element,false));bus.on('element.click',({element})=>{if(!childMode.value&&element?.type==='bpmn:ServiceTask')showChildPreview(element)});bus.on('element.dblclick',({element})=>{if(!childMode.value&&element?.type==='bpmn:ServiceTask')showChildPreview(element)})}
function updateSelectedProperty(key,value){if(selectedElement.value)modeler.value.get('modeling').updateProperties(selectedElement.value,{[key]:value||undefined})}
function actionGlyph(action){const key=String(action?.actionKey||'').toUpperCase();if(key.includes('VISION'))return'▣';if(key.includes('HOME'))return'↻';if(key.includes('PICK'))return'↑';if(key.includes('PLACE'))return'↓';if(key.includes('MOVE')||key.includes('MOTION'))return'✣';if(key.includes('GRIP'))return'⑂';if(key.includes('DOOR'))return'⇥';if(key.includes('LABEL'))return'▤';if(key.includes('GLOVE'))return'▧';return'◆'}
function createActionShape(action){const i=modeler.value,bo=i.get('bpmnFactory').create('bpmn:ServiceTask',{name:action.name,actionKey:action.actionKey,actionDefinitionId:action.actionDefinitionId||builtInActionDefinitionIds[action.actionKey],actionRevision:action.actionRevision,failureStrategy:'RETRY_THEN_SUSPEND'});return i.get('elementFactory').createShape({type:'bpmn:ServiceTask',businessObject:bo,width:180,height:66})}
function dragAction(event,action){if(event.button!=null&&event.button!==0)return;event.preventDefault();modeler.value.get('create').start(event,createActionShape(action))}
function addAction(){}
function eventExists(type){diagramRevision.value;return Boolean(modeler.value?.get('elementRegistry').filter(element=>element.type===type).length)}
function handleActionMouseDown(event){const button=event.target.closest?.('.workflow-editor-page .action-card:not(:disabled)');const key=button?.querySelector('small')?.textContent?.trim();if(!key)return;const action=allPaletteActions.value.find(item=>item.actionKey===key);if(action)dragAction(event,action)}
function refreshActionIcons(){nextTick(()=>document.querySelectorAll('.workflow-editor-page .action-card:not(.event-actions .action-card)').forEach(button=>{const key=button.querySelector('small')?.textContent?.trim(),action=allPaletteActions.value.find(item=>item.actionKey===key),icon=button.querySelector('.action-icon');if(action&&icon)icon.textContent=actionGlyph(action)}))}
function dragEvent(event,type,name){if(event.button!=null&&event.button!==0)return;const i=modeler.value;if(i.get('elementRegistry').filter(element=>element.type===type).length)return ElMessage.warning(`当前画布只能有一个${name}节点`);event.preventDefault();const bo=i.get('bpmnFactory').create(type,{name}),shape=i.get('elementFactory').createShape({type,businessObject:bo,width:180,height:66});i.get('create').start(event,shape)}
function zoom(value){const c=modeler.value?.get('canvas');if(!c)return;if(value==='fit')c.zoom('fit-viewport');else c.zoom(Math.min(2,Math.max(.35,c.zoom()+value)));zoomLevel.value=Math.round(c.zoom()*100)}
function normalizeFlowableXml(xml){return String(xml||'').replaceAll('<bpmn:serviceTask','<bpmn:receiveTask').replaceAll('</bpmn:serviceTask>','</bpmn:receiveTask>')}
function normalizeEditorXml(xml){return String(xml||'').replaceAll('<bpmn:receiveTask','<bpmn:serviceTask').replaceAll('</bpmn:receiveTask>','</bpmn:serviceTask>')}
async function importDiagram(xml){await modeler.value.importXML(normalizeEditorXml(xml));normalizeNodeBounds();normalizeSequenceFlows();await nextTick();modeler.value.get('canvas').zoom('fit-viewport');zoomLevel.value=Math.round(modeler.value.get('canvas').zoom()*100);refreshAllOverlays();refreshActionIcons();dirty.value=false}
function actionDefinitionIdFor(actionKey,legacy={}){return legacy.actionDefinitionId||legacy.actionId||actions.value.find(item=>item.actionKey===actionKey)?.actionDefinitionId||builtInActionDefinitionIds[actionKey]||''}
function restoreActionBindings(editorData={}){const nodes=Array.isArray(editorData.nodes)?editorData.nodes:[],properties=editorData.nodeProperties||{},modeling=modeler.value.get('modeling');modeler.value.get('elementRegistry').filter(element=>element.type==='bpmn:ServiceTask').forEach(element=>{const legacy=properties[element.id]||nodes.find(node=>node.bpmnNodeId===element.id)||{},key=element.businessObject.actionKey||legacy.actionKey||legacy.actionType||'',definitionId=element.businessObject.actionDefinitionId||actionDefinitionIdFor(key,legacy);modeling.updateProperties(element,{actionKey:key||undefined,actionDefinitionId:definitionId||undefined,actionRevision:element.businessObject.actionRevision||String(legacy.actionRevision||'')||undefined})})}
function serializeEditorData(){const previous=loadedEditorData.value||{},nodes=modeler.value.get('elementRegistry').filter(element=>element.type!=='label'&&element.businessObject).map((element,index)=>{const business=element.businessObject,isAction=element.type==='bpmn:ServiceTask';return{id:index+1,bpmnNodeId:element.id,name:business.name||element.id,nodeCategory:isAction?'MAIN':'EVENT',nodeType:isAction?'AGV 节点':'通用节点',position:{x:element.x,y:element.y},x:element.x,y:element.y,...(isAction?{actionKey:business.actionKey,actionType:business.actionKey,actionDefinitionId:business.actionDefinitionId,actionId:business.actionDefinitionId,actionRevision:business.actionRevision,status:'ACTIVE',executionParams:business.executionParams||{},failureStrategy:business.failureStrategy||'RETRY_THEN_SUSPEND'}:{actionType:'CUSTOM'})}}),nodeProperties=Object.fromEntries(nodes.map(node=>[node.bpmnNodeId,{...previous.nodeProperties?.[node.bpmnNodeId],...node}])) ;return{...previous,format:'bpmn-js',version:2,nodes,nodeProperties}}
async function returnToMain(saveChild=false){if(!childMode.value)return;let childXml='';if(saveChild)({xml:childXml}=await modeler.value.saveXML({format:true}));const parentId=childParentId.value,parentName=childParentName.value;childMode.value=false;await importDiagram(mainXmlCache.value);const parent=modeler.value.get('elementRegistry').get(parentId);if(saveChild&&parent){modeler.value.get('modeling').updateProperties(parent,{subProcessXml:childXml});dirty.value=true;ElMessage.success(`${parentName} 的子流程已保存`)}else ElMessage.info('已返回主流程');if(parent)modeler.value.get('selection').select(parent);childParentId.value='';childParentName.value=''}

async function migrateLegacy(data){await importDiagram(emptyDiagram(meta.templateName));if(!Array.isArray(data?.nodes)||!data.nodes.length)return;const i=modeler.value,registry=i.get('elementRegistry'),modeling=i.get('modeling'),canvas=i.get('canvas'),factory=i.get('elementFactory'),bpmnFactory=i.get('bpmnFactory'),root=canvas.getRootElement();modeling.removeElements(registry.filter(e=>e.parent&&e.type!=='label'));const map=new Map();for(const n of data.nodes){const type=n.name==='开始'?'bpmn:StartEvent':n.name==='结束'?'bpmn:EndEvent':'bpmn:ServiceTask',actionKey=n.actionKey||n.actionType||'CUSTOM';const bo=bpmnFactory.create(type,{name:n.name,...(type==='bpmn:ServiceTask'?{actionKey,actionDefinitionId:actionDefinitionIdFor(actionKey,n),actionRevision:String(n.actionRevision||''),executionParams:n.parameterText||n.executionParams?.raw||'',failureStrategy:n.failureStrategy||'RETRY_THEN_SUSPEND',completionBasis:n.completionBasis||''}:{})});const shape=factory.createShape({type,businessObject:bo});modeling.createShape(shape,{x:Number(n.x??n.position?.x??80)+(type.includes('Event')?18:50),y:Number(n.y??n.position?.y??100)+(type.includes('Event')?18:40)},root);map.set(String(n.id),shape)}for(const line of data.connections||[]){const source=map.get(String(line.from)),target=map.get(String(line.to));if(source&&target)modeling.connect(source,target,{type:'bpmn:SequenceFlow'})}canvas.zoom('fit-viewport');dirty.value=true;ElMessage.info('旧版画板已转换为 BPMN 2.0，保存后完成迁移')}

async function load(){loading.value=true;try{try{const[actionRows,sceneRows]=await Promise.all([getActions(),listActionBusinessScenes()]);actions.value=normalizeActions(actionRows);actionScenes.value=sceneRows||[]}catch(error){actions.value=normalizeActions([]);actionScenes.value=[];ElMessage.warning(`动作清单加载失败：${error.message}`)}if(!editingId){meta.templateNumber=`TPL-${Date.now().toString().slice(-8)}`;meta.templateName='新建流程模板';await importDiagram(blankMainDiagram(meta.templateName));restoreActionBindings();return}const d=await getWorkflow(editingId);Object.assign(meta,{id:d.id,templateNumber:d.templateNumber||String(editingId),templateName:d.templateName||'',applicableObject:d.applicableObject||'复合机器人',status:d.status==='ENABLED'||d.deployedVersion?'已启用 · 修改后转草稿':'草稿'});const editorData=typeof d.editorData==='string'?JSON.parse(d.editorData):d.editorData||{};loadedEditorData.value=editorData;if(d.bpmnXml?.includes('BPMNDiagram'))await importDiagram(d.bpmnXml);else await migrateLegacy(editorData);restoreActionBindings(editorData)}catch(error){ElMessage.error(`模板加载失败：${error.message}`);await importDiagram(emptyDiagram(meta.templateName||'流程模板'))}finally{loading.value=false}}
function validateDiagram(){const es=modeler.value.get('elementRegistry').filter(e=>e.businessObject&&e.type!=='label');if(es.filter(e=>e.type==='bpmn:StartEvent').length!==1||es.filter(e=>e.type==='bpmn:EndEvent').length!==1)return'流程必须且只能包含一个开始事件和一个结束事件';const mainNodes=es.filter(e=>e.type==='bpmn:ServiceTask');const missingChildren=mainNodes.find(e=>!parseChildRows(e.businessObject.subProcessXml).length);if(missingChildren)return`主节点“${missingChildren.businessObject.name||missingChildren.id}”尚未配置子节点，请先添加并保存子节点`;const missingKey=mainNodes.find(e=>!e.businessObject.actionKey);if(missingKey)return`动作任务“${missingKey.businessObject.name||missingKey.id}”缺少动作编码`;const missingDefinition=mainNodes.find(e=>!e.businessObject.actionDefinitionId);if(missingDefinition)return`可执行节点“${missingDefinition.businessObject.name||missingDefinition.id}”未绑定动作定义，请先保存该主节点的子节点`;return''}
async function save(){if(childMode.value)await returnToMain(true);if(!meta.templateName.trim())return ElMessage.warning('请填写模板名称');const error=validateDiagram();if(error)return ElMessage.warning(error);saving.value=true;try{const{xml}=await modeler.value.saveXML({format:true}),editorData=serializeEditorData();const result=await saveWorkflow({...meta.id&&{id:meta.id},templateName:meta.templateName.trim(),applicableObject:meta.applicableObject,bpmnXml:normalizeFlowableXml(xml),editorData});loadedEditorData.value=editorData;meta.id=result?.id||meta.id;meta.templateNumber=result?.templateNumber||meta.templateNumber;meta.status=result?.status==='ENABLED'?'已启用 · 修改后转草稿':'草稿';dirty.value=false;ElMessage.success('BPMN 流程模板已保存')}catch(error){ElMessage.error(`保存失败：${error.message}`)}finally{saving.value=false}}
onMounted(async()=>{document.addEventListener('mousedown',handleActionMouseDown,true);modeler.value=new BpmnModeler({container:canvasHost.value,moddleExtensions:{agv:agvModdle}});bindEvents(modeler.value);await load();refreshActionIcons()})
onBeforeUnmount(()=>{document.removeEventListener('mousedown',handleActionMouseDown,true);modeler.value?.destroy()})
</script>

<template><div class="page-view workflow-editor-page"><PageHeader class="page-head" title="流程模板" description="基于 BPMN 2.0 标准编排 AGV 动作、事件、网关和顺序流"><div class="header-actions"><span v-if="dirty" class="dirty-indicator">有未保存修改</span><router-link class="secondary-button" to="/workflows/templates">返回模板列表</router-link><button class="primary-button" type="button" :disabled="saving||loading" @click="save">{{saving?'保存中…':'保存 BPMN'}}</button></div></PageHeader>
<main class="editor-page-canvas"><section class="meta-panel"><div class="meta-heading"><div><h2>{{editingId?`编辑模板 · ${meta.templateNumber}`:'新建 BPMN 模板'}}</h2><p>保存标准 BPMN XML 与 BPMN DI，可被 Flowable 和其他 BPMN 工具读取。</p></div><span class="status-pill">{{meta.status}}</span></div><div class="meta-fields"><label><span>模板编号</span><input v-model="meta.templateNumber" @input="dirty=true"></label><label><span>模板名称</span><input v-model="meta.templateName" @input="dirty=true"></label><label><span>适用对象</span><select v-model="meta.applicableObject" @change="dirty=true"><option>复合机器人</option><option>贴标工作站</option><option>手套箱</option><option>后处理机台</option><option>检测工作站</option></select></label></div></section>
<section class="canvas-section"><div class="canvas-section-heading"><h2>Canvas 动作组合画布</h2><p>从左侧主节点清单拖入节点；点击主节点上的“配置子节点”查询并编辑对应子节点。</p></div><div class="modeler-shell"><aside class="action-panel"><div class="panel-title"><h3>动作清单</h3><span>⌃</span></div><input v-if="!childMode" v-model="actionKeyword" class="action-search" placeholder="搜索主节点名称或编码"><div class="action-group-label">通用节点</div><div class="action-list event-actions"><button type="button" class="action-card event-card" :disabled="eventExists('bpmn:StartEvent')" @mousedown="dragEvent($event,'bpmn:StartEvent','开始')"><span class="event-symbol start-symbol">➤</span><strong>开始</strong></button><button type="button" class="action-card event-card" :disabled="eventExists('bpmn:EndEvent')" @mousedown="dragEvent($event,'bpmn:EndEvent','结束')"><span class="event-symbol end-symbol">♟</span><strong>结束</strong></button></div><template v-for="group in paletteGroups" :key="group.label"><div v-if="group.items.length" class="action-group-label">{{group.label}}</div><div v-if="group.items.length" class="action-list"><button v-for="action in group.items" :key="action.actionKey" type="button" class="action-card" @click="addAction(action)"><span class="action-icon">◆</span><span><strong>{{action.name}}</strong><small>{{action.actionKey}}</small></span></button></div></template></aside>
<div :class="['canvas-column',{'with-toolbar':childMode}]"><div v-if="childMode" class="canvas-toolbar"><button class="back-main" type="button" @click="returnToMain(false)">← 返回主节点：{{childParentName}}</button><button class="save-child" type="button" @click="returnToMain(true)">保存并返回</button></div><div ref="canvasHost" :class="['bpmn-canvas',{'child-canvas':childMode}]"><div v-if="!childMode" class="floating-zoom"><button type="button" title="适应画布" @click="zoom('fit')">⛶</button><button type="button" title="缩小" @click="zoom(-.1)">−</button><span>{{zoomLevel}}%</span><button type="button" title="放大" @click="zoom(.1)">＋</button></div><section v-if="childPreviewVisible" class="child-preview-card" @mousedown.stop @click.stop><header><div><strong>主节点：{{childParentSequence}}</strong><span>→</span><b>{{childRows.length}} 个子节点</b></div><button class="edit-children-button" type="button" @click="openChildEditor">✎ 编辑子节点</button><button class="child-close" type="button" aria-label="关闭子节点预览" @click="childPreviewVisible=false">×</button></header><p>鼠标点击主节点可进入子节点</p><table><thead><tr><th>子节点序号</th><th>子节点名称</th></tr></thead><tbody><tr v-if="!childRows.length"><td colspan="2" class="child-empty">暂未配置子节点，点击“编辑子节点”添加</td></tr><tr v-for="(row,index) in childRows" :key="row.id" :class="{selected:selectedChildIndex===index}" @click="selectedChildIndex=index"><td>{{row.order}}</td><td>{{row.name}}</td></tr></tbody></table></section><div v-if="loading" class="loading-mask">正在加载 BPMN 模型…</div></div></div>
<aside class="properties-panel"><div class="panel-title"><h3>节点属性</h3><span>⌃</span></div><p class="property-subtitle">根据主节点或子节点选择自动切换</p><p v-if="!selectedElement" class="empty-properties">请选择画板中的节点</p><template v-else><div class="element-kind"><span>当前节点：{{propertyForm.name||selectedType.replace('bpmn:','')}}</span><small>{{selectedElement.id}}</small></div><label class="property-field"><span>节点名称</span><input v-model="propertyForm.name" disabled></label><label class="property-field"><span>节点分类</span><input :value="isActionTask?(childMode?'子节点':'AGV 节点'):'通用节点'" disabled></label><template v-if="isActionTask"><label class="property-field"><span>执行参数</span><textarea v-model="propertyForm.executionParams" rows="4" placeholder="参数待确认" @input="updateSelectedProperty('executionParams',propertyForm.executionParams)"></textarea></label><label class="property-field"><span>失败策略</span><select v-model="propertyForm.failureStrategy" @change="updateSelectedProperty('failureStrategy',propertyForm.failureStrategy)"><option value="RETRY_THEN_SUSPEND">按策略重试后挂起</option><option value="SUSPEND">立即挂起</option><option value="SKIP">跳过并记录</option></select></label><label class="property-field"><span>完成依据</span><textarea v-model="propertyForm.completionBasis" rows="3" placeholder="设备反馈 + 状态校验，待技术确认" @input="updateSelectedProperty('completionBasis',propertyForm.completionBasis)"></textarea></label></template><div v-else class="standard-note">标准 BPMN 事件或网关，可通过画板快捷菜单连接、替换或删除。</div></template></aside></div></section></main><div v-if="childEditorVisible" class="child-editor-overlay"><section class="child-editor-dialog" role="dialog" aria-modal="true"><header><div><h2>编辑子节点</h2><p><strong>主节点：{{childParentSequence}}</strong><span>→</span><b>{{childRows.length}} 个子节点</b></p><small>拖动右侧子节点可直接调整执行顺序</small></div><button type="button" aria-label="关闭子节点编辑" :disabled="childSaving" @click="childEditorVisible=false">×</button></header><div class="child-editor-content"><aside><h3>动作清单</h3><p>根据当前主节点从后端查询可用子节点</p><span>子节点</span><div><p v-if="childActionsLoading" class="child-action-state">正在加载子节点…</p><p v-else-if="!childActions.length" class="child-action-state">该主节点暂无可用子节点</p><button v-for="action in childActions" :key="action.actionKey" type="button" @click="addChildAction(action)"><i>{{actionGlyph(action)}}</i><strong>{{action.name}}</strong></button></div></aside><section><table><thead><tr><th>子节点序号</th><th>子节点名称</th><th></th></tr></thead><tbody><tr v-if="!childRows.length"><td colspan="3" class="child-empty">从左侧动作清单添加子节点</td></tr><tr v-for="(row,index) in childRows" :key="row.id" draggable="true" :class="{selected:selectedChildIndex===index,dragging:draggingChildIndex===index,'drop-target':childDropIndex===index&&draggingChildIndex!==index}" @click="selectedChildIndex=index" @dragstart="startChildDrag($event,index)" @dragover="overChildDrag($event,index)" @drop="dropChild($event,index)" @dragend="endChildDrag"><td><span class="child-drag-handle" title="拖动调整顺序">⋮⋮</span><span class="child-order-badge">{{row.order}}</span></td><td>{{row.name}}</td><td><button class="remove-child-button" type="button" title="删除子节点" @click.stop="removeChild(index)">×</button></td></tr></tbody></table></section></div><footer><button type="button" :disabled="childSaving" @click="childEditorVisible=false">关闭</button><button class="save-children-button" type="button" :disabled="childSaving" @click="saveChildEditor">{{childSaving?'保存中…':'保存流程'}}</button></footer></section></div></div></template>

